SELECT FROM common_setting
setting_key = #{settingKey}
ORDER BY CASE setting_key WHEN 'sessionIdleTime' THEN 1 WHEN 'pageSize' THEN 2 WHEN 'defaultSearchPeriod' THEN 3 WHEN 'bulkQueryThreshold' THEN 4 WHEN 'longRunningTaskNoticeThreshold' THEN 5 ELSE 99 END LIMIT #{size} OFFSET #{offset}
